---@param props ZStackProps
---@return Node
function ui.ZStack(props) end

--- A grid of equally sized cells. (Tier 1, since 1.0)
---@param props GridProps
---@return Node
function ui.Grid(props) end

--- Scrolls its content. (Tier 1, since 1.0)
---@param props ScrollViewProps
---@return Node
function ui.ScrollView(props) end

--- Flexible empty space. (Tier 1, since 1.0)
---@param props SpacerProps
---@return Node
function ui.Spacer(props) end

